function patternCategory(p){return ['preset_ichimatsu','preset_asanoha','preset_uroko'].includes(p.id)?'和服传统纹样':p.id.startsWith('preset_')?'精选纹样':'我的自绘'}
function effectivePattern(g){return g.pattern||themePatterns[g.c]}
function centeredPattern(p){if(p?.mode==='repeat')return false;return p&&(p.mode==='center'||(!p.id.startsWith('preset_')&&!p.id.startsWith('theme_'))||['preset_heart','preset_flower','preset_bow','preset_lantern'].includes(p.id))}
function patternSize(p){return p?.size===16||p?.cells?.length===256?16:8}
function patternSample(p,x,y){const n=patternSize(p);return p?.cells[((Math.floor(y)%n+n)%n)*n+(Math.floor(x)%n+n)%n]}
function paintWholeMotif(ctx,p,x,y,scale){if(!p)return;const n=patternSize(p),step=scale*8/n;for(let row=0;row<n;row++)for(let col=0;col<n;col++){const color=p.cells[row*n+col];if(color){ctx.fillStyle=color;ctx.fillRect(x+col*step,y+row*step,step,step)}}}
function itemMotifRects(r){if(sweaterTypes.includes(r))return ['cardigan','sailor','polo','halfzip'].includes(r)?[[27,48,2]]:[[32,44,4]];return {scarf:[[40,38,2]],socks:[[20,26,2]],bag:[[32,40,4]],hat:[[32,24,4]],mittens:[[17,24,2],[59,24,2]]}[r]||[]}
function itemMotif(ctx,g,fromRow,unit){const p=effectivePattern(g);if(!centeredPattern(p)||g.r==='sausage')return;ctx.save();ctx.beginPath();ctx.rect(0,fromRow*unit,96,96-fromRow*unit);ctx.clip();for(const [x,y,scale]of itemMotifRects(g.r))paintWholeMotif(ctx,p,x,y,scale);ctx.restore()}
