let lastSpeechAt=Date.now(),nextMurmur=Date.now()+45000;
const murmurs={idle:['今天的阳光，像一团没绕好的毛线。','你忙你的，我把尾巴收好一点。','如果毛线也会做梦，会梦到什么呢？','刚刚听见邮筒响了……也可能是我的肚子。','这里有你坐过的温度。'],knit:['再织一行，再抬头看看你。','这一针有一点歪，不过摸起来很软。','领口要松一点，才装得下一个大大的哈欠。','电视里下雪了，我想换一团暖色的线。','麻花绕来绕去，最后还是会见面的。','这件毛衣的口袋，可以装一颗小小的勇气。'],sleep:['呼……梦里也有一篮毛线。','晚安。明天再把袖子织完。'],bunny:['兔兔看起来很乖。只是看起来。','我数过了，围巾少的那几针一定不是风吹的。','它用腊肠狗围巾道歉的样子，还挺熟练。']};
function murmur(now){if(document.hidden||now<nextMurmur||now-lastSpeechAt<18000)return;const kind=state.bunny.active||state.bunny.chewed?'bunny':state.sleeping?'sleep':state.running?'knit':'idle',lines=murmurs[kind];say(lines[Math.floor(Math.random()*lines.length)]);nextMurmur=now+40000+Math.random()*25000}
function updatePetName(){document.title=(TEST_MODE?'测试小屋 · ':'')+state.petName+'的毛线小屋';$('petNameLabel').textContent=state.petName+'的毛线小屋';$('room').setAttribute('aria-label',state.petName+'在像素小屋里活动，编织时坐在电视旁挥动织针');$('giftTitle').textContent=state.petName+'的礼物篮';document.querySelector('.room-panel').setAttribute('aria-label',state.petName+'的家');document.querySelector('#basket span').textContent='看看'+state.petName+'的心意 →'}

let state=load(),account=null,remoteRevision=null,dirty=false,syncBusy=false,syncBlocked=false,accountReady=false,toastTimer,shopFilter='all',activeTab='shop',saveCounter=0;
function toast(t){$('toast').textContent=t.replaceAll('小花',state.petName);$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3500)}
function save(){try{localStorage.setItem(TEST_MODE?STORE:account?'calico-account-'+account.id:STORE,JSON.stringify(state));$('saveStatus').textContent=account?'账号存档 · 待同步':TEST_MODE?'测试存档 · 与正式游戏隔离':'访客存档 · 已保存在当前浏览器'}catch{$('saveStatus').textContent='浏览器存储不可用，请导出备份'}dirty=true}
function say(t){$('roomSpeech').textContent=t.replaceAll('小花',state.petName);lastSpeechAt=Date.now()}
function signature(){return state.recipe+'-'+state.theme+'-'+(state.patternId||'base')+(state.patternId&&state.patternLayout==='repeat'?'|repeat':'')+(selectedFinish()?'~s='+selectedFinish():'')+(homeRecipe(state.recipe)&&state.homeLayout!=='repeat'?'~h='+state.homeLayout:'')}
function duration(){return recipes[state.recipe].seconds}
function currentPattern(){const p=allPatterns().find(p=>p.id===state.patternId);return p?(state.patternLayout==='repeat'?{...p,mode:'repeat'}:p):null}
function randomRank(){const a=new Uint32Array(1);crypto.getRandomValues(a);const n=a[0]/4294967296;return n<.7?'R':n<.95?'SR':'SSR'}
function finishOne(){const r=state.recipe,c=state.theme,rank=randomRank(),p=currentPattern(),id=r+'-'+c+'-'+rank,gift={r,c,rank,reward:craftReward(r,rank),at:Date.now(),pattern:p?clone(p):null,finishStyle:selectedFinish(),homeLayout:homeRecipe(r)?state.homeLayout:undefined};if(p||gift.finishStyle||(homeRecipe(r)&&state.homeLayout!=='repeat')){const customId=id+'-'+(p?.id||'base')+(p?.mode==='repeat'?'|repeat':'')+(gift.finishStyle?'~s='+gift.finishStyle:'')+(homeRecipe(r)&&state.homeLayout!=='repeat'?'~h='+state.homeLayout:'');gift.customId=customId;state.custom[customId]={...gift,count:(state.custom[customId]?.count||0)+1}}else state.owned[id]=(state.owned[id]||0)+1;state.gifts.push(gift);state.coins+=gift.reward;state.made++;gainCraft(gift);state.mood=Math.min(100,state.mood+3);for(const o of orderDefs)if(o.recipe===r&&o.theme===c&&state.orders[o.id]==='accepted')state.orders[o.id]='ready';return gift}
function settle(now=Date.now()){const count=settleKnitting(now);settleFocus(now);state.lastTick=now;return count}
function settleKnitting(now){settleBunny(now);murmur(now);settleLetters(now);const previous=state.lastTick;state.lastTick=now;if(!state.running||state.sleeping)return 0;let seconds=Math.max(0,(now-previous)/1000);if(state.work)seconds=Math.min(seconds,8*3600);else if(document.hidden||seconds>3)return 0;let count=0;const id=signature();while(seconds>0&&state.running){const remaining=Math.max(0,duration()-(state.progress[id]||0));const used=Math.min(seconds,remaining);state.progress[id]=(state.progress[id]||0)+used;state.seconds+=used;seconds-=used;if(state.progress[id]>=duration()-.00001){state.progress[id]=0;finishOne();count++;state.running=false;if(count>=480)break}else break}if(count){save();renderLists();if(!document.hidden)say('小花把 '+count+' 份新礼物放进了篮子，忙完再看吧。')}return count}
function pause(){settle();state.play.focus.running=false;state.running=false;state.lastTick=Date.now();save();render()}
function selectedSetup(){state.recipe=$('recipe').value;state.theme=$('channel').value;state.patternId=$('patternChoice').value;state.patternLayout=$('patternLayout').value;save();render()}
$('focusDuration').onchange=()=>{settle();const f=state.play.focus;state.running=false;f.phase='work';f.duration=Number($('focusDuration').value);f.remaining=f.duration;f.running=false;f.lastTick=Date.now();f.result='';save();renderFocusClock()};
$('focusToggle').onclick=()=>{if(state.bunny.repairAt||activity==='clean'){toast('等猫猫收拾好，再开始专注。');return}if(recipes[state.recipe].quick){toast('袜子和小包用于快速看纹样；正式专注请选择围巾、帽子或毛衣。');return}settle();const f=state.play.focus;if(f.running){f.running=false;save();render();return}if(f.phase==='break'){f.running=true;f.lastTick=Date.now();save();render();return}if(state.sleeping){toast('先轻轻叫醒小花，再开始一起专注。');return}if(activity==='eat'){toast('小花吃完这口就来。');return}if(f.remaining<=0)f.remaining=f.duration;f.running=true;f.lastTick=Date.now();f.result='';state.work=true;state.running=true;state.lastTick=Date.now();save();render();say('这一段，我织毛线，你做自己的事。完成后奖励会安静收好。')};
$('todoForm').onsubmit=e=>{e.preventDefault();const text=$('todoInput').value.trim();if(!text)return;if(state.play.tasks.length>=30){toast('先收拾一下清单吧，最多保留 30 件小事。');return}state.play.tasks.push({id:'t'+Date.now().toString(36)+Math.random().toString(36).slice(2,5),text,done:false});$('todoInput').value='';save();renderTodos()};
$('cleanMess').onclick=()=>{if(!state.bunny.mess.length||state.bunny.repairAt||activity==='clean')return;if(state.sleeping){toast('先叫醒猫猫，再一起收拾。');return}pause();activity='clean';cleanStarted=0;say('小铲子出动，兔兔你先站旁边。')};
$('mendScarf').onclick=()=>{if(!state.bunny.chewed||state.bunny.repairAt||activity==='clean')return;if(state.sleeping){toast('先叫醒猫猫再修补。');return}pause();state.bunny.repairAt=Date.now()+20000;activity='mend';save();render();renderAlbum();say('破掉的地方，要一针一针补回来。')};
$('petBunny').onclick=()=>{if(!state.bunny.active)return;bunnyHappyUntil=performance.now()+4000;say('摸摸长耳朵……这次不许啃围巾哦。')};
$('feedBunny').onclick=()=>{if(!state.bunny.active)return;bunnyHappyUntil=performance.now()+5000;bunnySnackUntil=performance.now()+5000;say('给你一小片胡萝卜，慢慢嚼。')};
$('byeBunny').onclick=()=>{const b=state.bunny;if(!b.active)return;b.active=false;b.giftDue=0;b.nextAt=Date.now()+300000;save();render();say('兔兔回家啦，下次带着好习惯再来。')};
$('inviteBunny').onclick=()=>{if(Date.now()<state.bunny.nextAt)return;visitBunny()};
$('renamePet').onclick=()=>{$('petNameInput').value=state.petName;$('nameError').textContent='';$('nameDialog').showModal();$('petNameInput').focus()};$('cancelName').onclick=()=>$('nameDialog').close();
$('nameForm').onsubmit=e=>{e.preventDefault();const name=$('petNameInput').value.trim();if(!name||[...name].length>12){$('nameError').textContent='请输入 1～12 个字的名字。';return}state.petName=name;save();render();say('以后就叫我'+name+'啦。这个名字软软的，我喜欢。');$('nameDialog').close()};
$('recipe').onchange=selectedSetup;$('channel').onchange=selectedSetup;$('patternChoice').onchange=selectedSetup;$('patternLayout').onchange=selectedSetup;
$('workMode').onchange=()=>{settle();state.work=$('workMode').checked;state.lastTick=Date.now();save();render()};
$('knit').onclick=()=>{if(state.bunny.repairAt||activity==='clean'){toast('先把小残局收拾好，再继续编织。');return}if(!recipes[state.recipe].quick){settle();if(state.running){state.running=false;save();render();return}if(state.sleeping||activity==='eat'){toast('等猫猫醒来、吃好再继续织。');return}state.running=true;state.lastTick=Date.now();save();render();say('我继续织，你可以工作，也可以休息。');return}if(state.running){pause();return}if(state.sleeping||activity==='eat'){toast('等猫猫醒来、吃好再织小样吧。');return}settle();state.play.focus.running=false;state.running=true;state.work=true;state.lastTick=Date.now();save();render();say('先织一件小作品看看纹样，织好就收进篮子。')};
$('pat').onclick=()=>{if(state.sleeping){say('嘘，小花正做着毛线球的梦。');return}state.mood=Math.min(100,state.mood+8);heartUntil=performance.now()+1600;save();render();say('呼噜呼噜……小花蹭了蹭你的手。')};
$('feed').onclick=()=>feedCat(20,2,'日常猫粮');
function feedCat(food,mood,name){if(state.bunny.repairAt||activity==='clean'){toast('等猫猫忙完手里的活，再来吃饭。');return false}if(state.sleeping){toast('小花睡着了，叫醒后再吃吧。');return false}if(state.food>=100){toast('已经吃饱啦，这份先留着。');return false}pause();state.food=Math.min(100,state.food+food);state.mood=Math.min(100,state.mood+mood);activity='eat';catTarget=78;activityEnd=performance.now()+Math.abs(catX-78)/62*1000+5000;save();render();say('啊呜，'+name+'真好吃。');return true}
$('sleep').onclick=()=>{if(state.bunny.repairAt||activity==='clean'){toast('等猫猫收拾完再休息。');return}pause();state.sleeping=!state.sleeping;activity=state.sleeping?'sleep':'idle';catTarget=state.sleeping?555:320;save();render();say(state.sleeping?'睡一觉，醒来再织。':'伸个懒腰，又能陪你啦。')};
function timeLabel(n){n=Math.floor(n);const h=Math.floor(n/3600);return(h?h+':':'')+String(Math.floor(n/60)%60).padStart(2,'0')+':'+String(n%60).padStart(2,'0')}
function unfinishedProjects(){return Object.entries(state.progress).flatMap(([key,progress])=>{const [r,c,...parts]=key.split('-'),rawParts=parts.join('-').split('~'),rawPid=rawParts[0],style=rawParts.find(v=>v.startsWith('s='))?.slice(2)||'',home=rawParts.find(v=>v.startsWith('h='))?.slice(2)||'repeat',layout=rawPid.endsWith('|repeat')?'repeat':'original',pid=layout==='repeat'?rawPid.slice(0,-7):rawPid;if(!recipes[r]||recipes[r].giftOnly||!themes[c]||progress<=0||progress>=recipes[r].seconds)return [];const pattern=pid==='base'?null:allPatterns().find(p=>p.id===pid);if(pid!=='base'&&!pattern)return [];return [{key,r,c,layout,style,home,pid:pattern?.id||'',progress,name:themes[c].prefix+recipes[r].name+(pattern?' · '+pattern.name:'')+(layout==='repeat'?' · 整件重复':'')+(style?' · '+finishLabel(style):'')+(home!=='repeat'?' · '+(home==='solid'?'素色':'边缘织花'):''),left:recipes[r].seconds-progress}]})}
function renderUnfinished(){const list=unfinishedProjects(),select=$('unfinishedSelect'),old=select.value;const options=list.map(g=>[g.key,g.name+' · 剩余 '+(recipes[g.r].quick?Math.ceil(g.left)+' 秒':Math.ceil(g.left/60)+' 分钟')]);const version=JSON.stringify(options);if(select.dataset.version!==version){select.replaceChildren();if(!list.length)select.add(new Option('暂时没有未织完的作品',''));for(const [key,label]of options)select.add(new Option(label,key));if(list.some(g=>g.key===old))select.value=old;select.dataset.version=version}select.disabled=!list.length||state.running;$('resumeUnfinished').disabled=!list.length||state.running;}
$('resumeUnfinished').onclick=()=>{if(state.running)return;if(state.sleeping||activity==='eat'||activity==='clean'||state.bunny.repairAt){toast('等猫猫忙完或醒来，再继续织。');return}const g=unfinishedProjects().find(g=>g.key===$('unfinishedSelect').value);if(!g)return;settle();state.recipe=g.r;state.theme=g.c;state.patternId=g.pid;state.patternLayout=g.layout;state.finishStyle=g.style;state.homeLayout=g.home;save();render();$('knit').click();};
function render(){renderFinishChoices();$('homeLayoutLabel').hidden=!homeRecipe(state.recipe);$('homeLayout').value=state.homeLayout;$('homeLayout').disabled=state.running;$('patternLayout').value=state.patternLayout||'original';$('patternLayout').disabled=state.running||!state.patternId;$('patternRelation').textContent=currentPattern()?.mode==='repeat'?'整件重复纹样：以完整图案为单元铺满织物，保留领口和收边。':currentPattern()?'当前：'+themes[state.theme].name+'底色与收边 + '+currentPattern().name+'；主图保留原色，主图完整织入，周围使用同源小纹样；不同品质改变织花布局。':'主题搭配：'+themePatterns[state.theme].name+'；切换主题时配色与默认纹样一起变化。';renderUnfinished();updatePetName();renderBunny();renderFocusClock();renderKnitPreview();$('removeDisplay').hidden=!state.equipped.display;for(const k of ['food','mood']){$(k).value=state[k];$(k+'Text').textContent=Math.round(state[k])}$('coins').textContent=state.coins;$('made').textContent=state.made;$('companionTime').textContent=timeLabel(state.seconds);$('basketCount').textContent=state.gifts.length;$('workMode').checked=state.work;$('recipe').value=state.recipe;$('channel').value=state.theme;$('patternChoice').value=state.patternId;for(const id of ['recipe','channel','patternChoice'])$(id).disabled=state.running;const pct=Math.min(100,(state.progress[signature()]||0)/duration()*100);$('knitProgress').value=pct;$('progressText').textContent=Math.floor(pct)+'%';$('currentProject').textContent=themes[state.theme].prefix+recipes[state.recipe].name+(currentPattern()?' · '+currentPattern().name:'');$('knitStatus').textContent=(state.running?(state.work?'工作陪伴中':'安静编织中'):'已暂停')+' · 本件剩余 '+Math.ceil(duration()*(1-pct/100)/60)+' 分钟 · 约 '+Math.ceil(duration()/1500)+' 段标准番茄钟 · 本件完成后停下';$('knit').textContent=state.running?'暂停编织，保留进度':'开始 / 继续编织';if(recipes[state.recipe].quick){$('knitStatus').textContent=(state.running?'快速编织中':'快速作品')+' · 剩余 '+Math.ceil(duration()*(1-pct/100))+' 秒 · 织一件后停下';$('knit').textContent=state.running?'暂停，保留小样进度':'织一件小作品 · '+recipes[state.recipe].seconds+' 秒'}$('rewardPreview').textContent=recipes[state.recipe].quick?'纹样试织：不发毛线币，不计专注奖励；成品照常收藏。':'本件完成奖励：R '+craftReward(state.recipe,'R')+' / SR '+craftReward(state.recipe,'SR')+' / SSR '+craftReward(state.recipe,'SSR')+' ◈';$('sleep').textContent=state.sleeping?'☀ 轻轻叫醒':'☾ 睡一会儿';$('catState').textContent=state.sleeping?'● 休息中':state.running?'● 边看边织':activity==='clean'?'● 收拾小残局':state.bunny.repairAt?'● 一针一针修补':activity==='eat'?'● 吃点好吃的':'● 自由活动';$('roomClock').textContent=new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'});$('collectionCount').textContent=Object.keys(state.owned).filter(k=>state.owned[k]>0).length+' / '+(Object.values(recipes).filter(r=>!r.giftOnly).length*Object.keys(themes).length*Object.keys(ranks).length+bunnyScarves.length+(state.owned['sausage-bakery-SR']?1:0))+' · 纹样作品 '+Object.values(state.custom).filter(g=>g.count>0).length+' 款';}
function productArt(g){const c=document.createElement('canvas');c.width=40;c.height=32;const x=c.getContext('2d');const rect=(a,b,w,h,color)=>{x.fillStyle=color;x.fillRect(a,b,w,h)};const ink='#6c5944';if(g.id==='christmasTree'){rect(18,24,5,6,ink);for(let i=0;i<4;i++)rect(18-i*3,6+i*5,5+i*6,6,'#527957');rect(19,2,3,5,'#efcc70');rect(13,17,3,3,'#c47459');rect(24,22,3,3,'#efcc70');rect(5,26,9,6,'#b95546');return c}if(g.id==='christmasLights'){rect(7,8,26,2,ink);for(let i=8;i<33;i+=6)rect(i,10,3,4,i%2?'#b95546':'#e5bd65');rect(14,17,14,12,'#527957');rect(18,20,6,6,'#eee2c8');rect(18,17,5,3,'#b95546');return c}if(g.theme){const p=furnitureThemes[g.theme];rect(5,8,30,20,p.wood);rect(7,10,26,15,p.light);if(g.slot==='window'){rect(13,9,14,16,'#add1cf');rect(19,9,2,16,p.trim);rect(13,16,14,2,p.trim);rect(6,7,6,20,p.cloth);rect(28,7,6,20,p.cloth)}else if(g.slot==='tv'){rect(9,3,22,16,ink);rect(11,5,18,12,'#839d98');rect(8,24,24,2,p.trim)}else if(g.slot==='bed'){rect(8,12,24,12,p.cloth);rect(12,14,16,8,p.trim)}else if(g.slot==='desk'){rect(8,27,3,4,ink);rect(29,27,3,4,ink);rect(10,4,12,5,p.trim);rect(25,2,5,7,p.cloth)}else{rect(7,17,26,2,ink);for(let a=10;a<30;a+=7){rect(a,11,5,5,p.cloth);rect(a,21,5,4,p.trim)}}return c}if(g.type==='wear'){if(g.id==='bow'){rect(8,11,10,9,g.color);rect(22,11,10,9,g.color);rect(17,13,6,5,'#eed3c4');rect(10,12,3,3,'#ecc4c2')}else if(g.id==='beret'){rect(8,13,25,9,g.color);rect(12,9,17,5,g.color);rect(22,6,3,5,ink);rect(8,21,25,3,ink);rect(13,12,11,2,'#d9ae7b')}else{rect(12,6,16,19,g.color);rect(8,9,24,8,g.color);rect(14,7,12,3,'#e5d6ad');rect(17,15,6,7,'#ddcfaa');rect(12,25,16,2,ink)}}else if(g.type==='food'){if(g.id==='fish'){rect(7,17,27,6,'#c0c5b1');rect(12,12,15,8,g.color);rect(27,10,5,11,g.color);rect(14,14,2,2,ink);rect(16,15,8,1,'#d7e2d4')}else{rect(10,22,23,3,'#a7b5b4');rect(13,12,17,11,g.color);rect(16,8,11,5,g.color);rect(15,12,13,3,'#b97e50');rect(20,5,4,4,'#c37569')}}else if(g.slot==='wall'){rect(8,5,24,23,g.color);for(let a=10;a<32;a+=6)rect(a,5,1,23,'#ffffff55');rect(8,26,24,3,ink)}else if(g.slot==='rug'){rect(5,8,30,19,g.color);rect(8,11,24,13,'#d4d6b3');rect(11,14,18,7,g.color);for(let a=6;a<35;a+=4){rect(a,5,1,3,ink);rect(a,27,1,3,ink)}}else if(g.slot==='plant'){rect(15,19,13,10,'#b8805e');rect(20,7,3,14,'#67835d');rect(12,9,8,5,g.color);rect(23,4,8,6,g.color);rect(17,1,6,8,g.color)}else if(g.slot==='lamp'){rect(19,12,3,15,ink);rect(13,26,16,3,ink);rect(12,7,18,8,g.color);rect(15,4,12,4,g.color);rect(13,14,16,2,'#fff1bc')}else{rect(7,4,26,25,ink);rect(9,6,22,21,'#cba879');rect(9,15,22,3,ink);for(let a=11;a<30;a+=6)rect(a,8,4,7,['#8fa486','#c58c76','#9aacb8'][Math.floor(a/6)%3])}return c}
function switchTab(name){activeTab=name;for(const b of document.querySelectorAll('[data-tab]')){const on=b.dataset.tab===name;b.classList.toggle('selected',on);b.setAttribute('aria-selected',String(on))}for(const n of ['shop','album','closet','patterns','focus','studio','bunny'])$(n+'Panel').hidden=n!==name;if(name==='patterns')paintEditor();if(name==='focus')renderPlay();if(name==='studio')renderStudio();if(name==='bunny')renderBunnyWardrobe()}
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>switchTab(b.dataset.tab));
document.querySelectorAll('[data-shop]').forEach(b=>b.onclick=()=>{shopFilter=b.dataset.shop;document.querySelectorAll('[data-shop]').forEach(el=>el.classList.toggle('selected',el===b));renderShop()});
function buy(id){const g=byGood[id];if(!g)return;if(g.type!=='food'&&state.inventory[id]){equip(id);return}if(state.coins<g.price){toast('毛线币还差 '+(g.price-state.coins)+' 枚，织点小礼物就能攒到。');return}state.coins-=g.price;state.inventory[id]=(state.inventory[id]||0)+1;if(g.type!=='food')state.equipped[g.slot]={source:'shop',id};save();render();renderLists();toast(g.type==='food'?g.name+'已放进背包。':'换上了'+g.name+'，小屋又温暖了一点。')}
function equip(id){const g=byGood[id];if(!g||!state.inventory[id])return;if(g.type==='food'){if(!feedCat(g.food,g.mood,g.name))return;state.inventory[id]--}else{const current=state.equipped[g.slot];state.equipped[g.slot]=current?.id===id?null:{source:'shop',id}}save();render();renderLists()}
function makeProduct(g,closet=false){const card=document.createElement('article');card.className='product';const art=document.createElement('div');art.className='product-art';art.append(productArt(g));const price=document.createElement('span');price.className='price';price.textContent=closet?'拥有 '+state.inventory[g.id]:g.price+' ◈';art.append(price);const title=document.createElement('h3');title.textContent=g.name;const desc=document.createElement('p');desc.textContent=g.desc;const button=document.createElement('button');const own=state.inventory[g.id]>0,on=state.equipped[g.slot]?.id===g.id;button.textContent=closet?(g.type==='food'?'喂给小花':on?'收起来':'换上 / 摆放'):(g.type!=='food'&&own?(on?'已使用 · 收起来':'已拥有 · 换上'):'兑换 '+g.price+' ◈');button.onclick=()=>closet?equip(g.id):buy(g.id);card.append(art,title,desc,button);return card}
function renderShop(){$('shopGrid').replaceChildren(...goods.filter(g=>shopFilter==='all'||g.type===shopFilter).map(g=>makeProduct(g)));const owned=goods.filter(g=>state.inventory[g.id]>0);$('closetGrid').replaceChildren(...owned.map(g=>makeProduct(g,true)));if(!owned.length){const p=document.createElement('p');p.className='section-note';p.textContent='这里还空空的。去杂货铺挑一件喜欢的小东西吧。';$('closetGrid').append(p)}}
