function itemTitle(g){if(g.r==='sausage')return '兔兔赔礼 · '+bunnyScarf(g).name;return(g.pattern?g.pattern.name+(g.pattern.mode==='repeat'?' · 满版 · ':''):themes[g.c].prefix+(g.rank==='SSR'?'星织':g.rank==='SR'?'花织':'素织'))+recipes[g.r].name+(g.finishStyle?' · '+finishLabel(g.finishStyle):'')}
function sweaterMask(type,x,y){if(x<0||x>23||y<0||y>23)return false;const hem=type==='sailor'?19:21;let body=x>=6&&x<=17&&y>=6&&y<=hem;const sleeve=type==='vest'?false:y>=6&&y<=16&&((x>=Math.max(1,5-Math.floor((y-4)/2))&&x<=5)||(x>=18&&x<=Math.min(22,18+Math.floor((y-4)/2))));if(y>=4&&y<=7&&x>=5&&x<=18)body=true;if(y<8&&x>=9&&x<=14)body=false;if(['cardigan','vest','sailor'].includes(type)&&y<11&&Math.abs(x-11.5)<(11-y)*.6)body=false;if(type==='hoodie'&&y>=1&&y<=6&&x>=8&&x<=15)body=!(x>=10&&x<=13&&y>=2&&y<=5);if(type==='halfzip'&&y>=2&&y<=5&&x>=9&&x<=14)body=true;return body||sleeve}
