const hem=g.r==='sailor'?18:20;if(y>=hem||(y>=15&&(x<6||x>17))){f(px,py,4,4,a);f(px+1,py,1,4,'#fff4df66');f(px+3,py,1,4,'#463a3833')}
if(x===6||x===17)f(px+1,py,1,4,'#493d3822');
