function blendYarn(a,b,t){const rgb=[0,2,4].map(i=>Math.round(parseInt(a.slice(1+i,3+i),16)*(1-t)+parseInt(b.slice(1+i,3+i),16)*t).toString(16).padStart(2,'0'));return '#'+rgb.join('')}
const fabricPalettes=new Map();
function fabricPalette(g){const theme=themes[g.c],p=effectivePattern(g),counts=new Map();for(const c of p?.cells||[])if(c)counts.set(c,(counts.get(c)||0)+1);const colors=[...counts].sort((a,b)=>b[1]-a[1]).map(a=>a[0]);const transparent=p?.cells.some(c=>!c),base=transparent?blendYarn(theme.color,'#fff4e3',.65):(colors[0]||theme.color),ink=colors.find(c=>c!==base)||theme.accent;return {base,soft:blendYarn(base,ink,.16),dark:blendYarn(ink,'#302b32',.25),cream:blendYarn(base,'#fff4e3',.65),accent:ink}}
