if(!center){const panel=isSweater?((g.r==='crew'||g.r==='hoodie'||g.r==='polo'||g.r==='halfzip')&&y>=10&&y<=13&&x>=7&&x<=16):g.r==='bag'&&x>=5&&x<=10&&y>=7&&y<=10;if(panel)result=color;else if(isSweater&&['cardigan','vest','sailor','fairisle'].includes(g.r)&&y>=17&&y<=19&&x>=7&&x<=16)result=color;else if(g.r==='cable'&&(x<6||x>17)&&y>=10&&y<=13)result=color;else if(g.r==='hat'&&y>=6&&y<=8)result=color;else if(g.r==='socks'&&y>=4&&y<=6)result=color}
