// A small yarn pompom, joined to the crown rather than floating above it.
box(cx-2,top-5,5,5,p.accent);box(cx-4,top-3,9,3,p.accent);box(cx-1,top-4,3,1,p.cream);
wornMotif(g,cx-6,top+5,bunny?1:1.5);
